    function isPalinSent(s) {
    // create an array to store only 
    // alphanumeric characters
    let s1 = [];
    for (let i = 0; i < s.length; i++) {
        let ch = s[i];

        // Check if the character is alphanumeric
        if (/[a-zA-Z0-9]/.test(ch)) {
            s1.push(ch.toLowerCase());
        }
